import "core-js/modules/es6.string.link";
import "core-js/modules/es6.regexp.split";
import "core-js/modules/es6.function.name";
import { getDictList } from "@/api/dict";
import { resourceSave, uploadFile1 } from "@/api/ictOperation/index";
import website from '@/config/website';
import { Base64 } from 'js-base64';
import { getToken } from '@/util/auth';
export default {
  props: ['isShow', 'tag'],
  data: function data() {
    return {
      submitForm: {
        path: '',
        fileName: '',
        title: '',
        tag: '',
        coverPhoto: ''
      },
      rules: {
        title: [{
          required: true,
          message: '资源标题不能为空',
          trigger: 'blur'
        }],
        content: [{
          required: true,
          message: '资源内容不能为空',
          trigger: 'blur'
        }],
        tag: [{
          required: true,
          message: '资源标签不能为空',
          trigger: 'blur'
        }],
        path: [{
          required: true,
          message: '附件不能为空',
          trigger: 'blur'
        }],
        coverPhoto: [{
          required: true,
          message: '封面不能为空',
          trigger: 'change'
        }]
      },
      tagsList: [],
      action: '#',
      // /api/idevelop-resource/oss/endpoint/put-file
      headers: {
        Authorization: "Basic ".concat(Base64.encode("".concat(website.clientId, ":").concat(website.clientSecret))),
        'Idevelop-Auth': 'bearer ' + getToken()
      },
      tipsText: '',
      acceptType: '',
      fileList: [],
      acceptCoverType: '.jpg,.png',
      coverFileList: [],
      saveLoading: false
    };
  },
  mounted: function mounted() {
    this.initForm();
    this.getDict();
  },
  methods: {
    uploadFile2: function uploadFile2(params) {
      var file = params.file;
      var formData = new FormData();
      formData.append("file", file);
      uploadFile1(formData).then(function (res) {
        params.onSuccess(res);
      }).catch(function (error) {
        params.onError(error);
      });
    },
    uploadFile22: function uploadFile22(params) {
      var file = params.file;
      var formData = new FormData();
      formData.append("file", file);
      uploadFile1(formData).then(function (res) {
        params.onSuccess(res);
      }).catch(function (error) {
        params.onError(error);
      });
    },
    // 初始化表单
    initForm: function initForm() {
      this.submitForm.tag = this.tag;
      if (this.tag == 0) {
        this.tipsText = '只能上传word、pdf、xmind、ppt类型文件,且不超过100M（允许上传数量1个）';
        this.acceptType = '.pdf,.docx,.doc,.xmind,.ppt,.pptx';
      } else {
        this.tipsText = '只能上传mp4、wmv、asf、asx、rm、rmvb格式的视频文件,且不超过100M（允许上传数量1个）';
        this.acceptType = '.mp4,.wmv,.asf,.asx,.rm,.rmvb';
      }
      this.$forceUpdate();
    },
    // 获得字典
    getDict: function getDict() {
      var _this = this;
      getDictList("control_resource_type").then(function (res) {
        _this.tagsList = res.data;
      });
    },
    handleTag: function handleTag(val) {
      if (val == 0) {
        this.tipsText = '只能上传word、pdf、xmind、ppt类型文件（允许上传数量1个）';
        this.acceptType = '.pdf,.docx,.doc,.xmind,.ppt,.pptx';
      } else if (val == 1) {
        this.tipsText = '只能上传mp4、wmv、asf、asx、rm、rmvb格式的视频文件（允许上传数量1个）';
        this.acceptType = '.mp4,.wmv,.asf,.asx,.rm,.rmvb';
      }
      this.$refs.uploadFile.clearFiles();
      this.submitForm.path = '';
      this.submitForm.fileName = '';
      this.$set(this.submitForm, 'title', '');
      this.$forceUpdate();
    },
    // 上传前回调
    beforeUpload: function beforeUpload(file) {
      var ext = file.name.substring(file.name.lastIndexOf('.')).toLowerCase();
      var fileTypes = this.acceptType.split(',');
      var isCanUpload = true;
      for (var i = 0; i < fileTypes.length; i++) {
        var item = fileTypes[i];
        if (ext.indexOf(item) > -1) {
          isCanUpload = true;
          break;
        } else {
          isCanUpload = false;
        }
      }
      if (!isCanUpload) {
        this.$message({
          message: '只能上传提示给出的文件类型！',
          type: 'warning'
        });
      }
      if (file.size > 100 * 1024 * 1024) {
        this.$message({
          message: '文件大小不能超过100M',
          type: 'warning'
        });
        return false;
      }
      return isCanUpload;
    },
    // 上传成功回调
    handleFileSuccess: function handleFileSuccess(res, file, fileList) {
      this.submitForm.path = res.data.link;
      this.submitForm.fileName = res.data.originalName;
      this.$set(this.submitForm, 'title', res.data.originalName.split('.')[0]);
      // this.$forceUpdate()
      this.$refs.submitForm.validateField('path');
    },
    handleRemove2: function handleRemove2(file, fileList) {
      this.submitForm.path = '';
      this.submitForm.fileName = '';
      this.$set(this.submitForm, 'title', '');
      this.$refs.submitForm.validateField('path');
    },
    // 封面上传
    beforeCoverUpload: function beforeCoverUpload(file) {
      var ext = file.name.substring(file.name.lastIndexOf('.')).toLowerCase();
      if (!(ext.indexOf('jpg') > -1 || ext.indexOf('png') > -1)) {
        this.$message({
          message: '请上传jpg或png格式的图片',
          type: 'warning'
        });
        return ext.indexOf('jpg') > -1 || ext.indexOf('png') > -1;
      }
      if (file.size > 500 * 1024) {
        this.$message({
          message: '封面大小不能超过500kb',
          type: 'warning'
        });
        return false;
      }
    },
    handleCoverFileSuccess: function handleCoverFileSuccess(res, file, fileList) {
      this.$set(this.submitForm, 'coverPhoto', res.data.link);
      // this.$forceUpdate()
      this.$refs.submitForm.validateField('coverPhoto');
    },
    handleRemove: function handleRemove(file, fileList) {
      // console.log(3321, file, fileList)
      this.$set(this.submitForm, 'coverPhoto', '');
      this.$refs.submitForm.validateField('coverPhoto');
    },
    handleExceed: function handleExceed() {
      this.$message({
        message: '只能上传一张封面！',
        type: 'warning'
      });
    },
    // 保存
    save: function save() {
      var _this2 = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          _this2.saveLoading = true;
          resourceSave(_this2.submitForm).then(function (res) {
            if (res.code == 200) {
              _this2.$message({
                message: '新增成功！',
                type: 'success'
              });
              _this2.saveLoading = false;
              _this2.$emit('addResource');
            }
          });
        } else {
          _this2.$message({
            message: '请完善表单项',
            type: 'warning'
          });
        }
      });
    }
  }
};
